const item = $('Buscar Tarea Pendiente').item.json;
const research = $json.stdout || '';

const systemPrompt = 'Sos un analista senior que consolida investigaciones de mercado en un documento único, coherente y accionable. Respondé en español, en formato markdown. Si detectás información contradictoria entre las secciones, marcala explícitamente como discrepancia.';
const userPrompt = `Consolidá la siguiente investigación en un único documento de síntesis para el proyecto "${item.ProjectName}":\n\n${research}\n\nEl documento final debe incluir: 1) Resumen ejecutivo, 2) Oportunidad de mercado, 3) Competencia clave, 4) Usuario objetivo y su problema principal, 5) Riesgos u observaciones, 6) Discrepancias detectadas (si las hay).`;

const body = {
  model: 'openai/gpt-4o-mini',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{ json: { ...item, requestBody: JSON.stringify(body) } }];

const item = $('Buscar Tarea Pendiente').item.json;
const response = $json;
const content = response.choices?.[0]?.message?.content || '';
const usage = response.usage || {};

const consolidatedMd = `# Research Consolidado — ${item.ProjectName}\n\n${content}\n`;

const reportMd = `# Reporte de Etapa — AIQ-PF-03-ResearchSynthesis\n\n` +
  `**Proyecto:** ${item.ProjectName} (${item.Slug})\n` +
  `**Fecha:** ${new Date().toISOString()}\n` +
  `**Modelo usado:** ${response.model || 'desconocido'}\n` +
  `**Tokens:** entrada ${usage.prompt_tokens ?? '?'} / salida ${usage.completion_tokens ?? '?'}\n\n` +
  `## Archivos generados\n- research/research-consolidated.md\n\n` +
  `## Resumen\n${content.slice(0, 500)}${content.length > 500 ? '...' : ''}\n`;

return [{
  json: {
    ...item,
    consolidatedMdB64: Buffer.from(consolidatedMd, 'utf8').toString('base64'),
    reportMdB64: Buffer.from(reportMd, 'utf8').toString('base64')
  }
}];
